import express, { ErrorRequestHandler, Express } from 'express';
import { TaskManagementService } from '../application/task-management-service';
import { ConflictError, DomainError, NotFoundError } from '../domain/errors';
import { InMemoryProjectRepository, InMemoryTaskRepository, InMemoryUserRepository, SequentialIdGenerator } from './in-memory-repositories';
import { TaskController } from './task-controller';

export function createApp(): Express {
  const service = new TaskManagementService(new InMemoryUserRepository(), new InMemoryProjectRepository(), new InMemoryTaskRepository(), new SequentialIdGenerator());
  const app = express();
  app.use(express.json());
  app.use(new TaskController(service).router());
  app.use(errorHandler);
  return app;
}

const errorHandler: ErrorRequestHandler = (error: unknown, _request, response, _next) => {
  if (error instanceof NotFoundError) { response.status(404).json({ error: error.message }); return; }
  if (error instanceof ConflictError) { response.status(409).json({ error: error.message }); return; }
  if (error instanceof DomainError || error instanceof TypeError) { response.status(400).json({ error: error.message }); return; }
  response.status(500).json({ error: 'Internal server error' });
};

export function startServer(port = Number(process.env.PORT) || 3000) {
  return createApp().listen(port);
}

if (require.main === module) startServer();

